38	/// 统一错误响应：`{"error": "...", 可选的定位字段}`，不改变任何已有数据。
39	struct ApiError {
40	    status: StatusCode,
41	    body: Value,
42	}
43	
44	impl ApiError {
45	    fn new(status: StatusCode, message: impl Into<String>) -> Self {
46	        ApiError {
47	            status,
48	            body: json!({ "error": message.into() }),
49	        }
50	    }
51	}
52	
53	impl IntoResponse for ApiError {
54	    fn into_response(self) -> Response {
55	        (self.status, Json(self.body)).into_response()
56	    }
57	}
58	
59	#[derive(Deserialize)]
60	struct WriteRequest {
61	    /// 写入的记录数组；与 `delete` 互斥，缺省时按写入处理（空批次仍为 400）。
62	    #[serde(default)]
63	    records: Option<Vec<Value>>,
64	    /// 是否允许用新内容替换同主键的已有记录；缺省为 false，行为与不支持替换时一致。
65	    #[serde(default)]
66	    replace: bool,
67	    /// 删除请求：按给出的字符串主键逐条删除当前数据；非空时本请求为删除请求。
68	    #[serde(default)]
69	    delete: Option<Vec<Value>>,
70	}
71	
72	/// 整批被业务规则拒绝时的统一响应体：`error` + `index` +（可识别时的）`id`。
73	fn rejection_error(r: BatchError) -> ApiError {
74	    match r {
75	        BatchError::Rejected(r) => ApiError {
76	            status: StatusCode::BAD_REQUEST,
77	            body: json!({
78	                "error": r.reason,
79	                "index": r.index,
80	                "id": r.id,
81	            }),
82	        },
83	        BatchError::Persist(msg) => ApiError::new(StatusCode::INTERNAL_SERVER_ERROR, msg),
84	    }
85	}
86	
87	/// `POST /collections/{collection}/records`：提交一批记录或一批删除（全有或全无）。
88	async fn write_records(
89	    State(s): State<Arc<Store>>,
90	    Path(collection): Path<String>,
91	    payload: Result<Json<WriteRequest>, axum::extract::rejection::JsonRejection>,
92	) -> Result<Json<Value>, ApiError> {
93	    let Json(req) = payload.map_err(|e| ApiError::new(StatusCode::BAD_REQUEST, e.body_text()))?;
94	
95	    // `records` 与 `delete` 同时出现：整批拒绝，不产生任何效果。
96	    if req.records.is_some() && req.delete.is_some() {
97	        return Err(ApiError::new(
98	            StatusCode::BAD_REQUEST,
99	            "\"records\" and \"delete\" must not appear in the same request",
100	        ));
101	    }
102	
103	    // 删除请求：按主键逐条删除当前数据，主键缺失幂等跳过。
104	    if let Some(ids) = req.delete {
105	        if ids.is_empty() {
106	            return Err(ApiError::new(
107	                StatusCode::BAD_REQUEST,
108	                "delete must be a non-empty array",
109	            ));
110	        }
111	        let out = s.delete_batch(&collection, &ids).map_err(rejection_error)?;
112	        return Ok(Json(json!({
113	            "collection": out.collection,
114	            "accepted": out.accepted,
115	            "deleted": out.deleted,
116	            "missing": out.missing,
117	        })));
118	    }
119	
120	    // 写入请求（缺省行为与原来完全一致）。
121	    let records = req.records.unwrap_or_default();
122	    if records.is_empty() {
123	        return Err(ApiError::new(
124	            StatusCode::BAD_REQUEST,
125	            "records must be a non-empty array",
126	        ));
127	    }
128	    match s.write_batch(&collection, &records, req.replace) {
129	        Ok(out) => {
130	            // replace=false（或缺省）时响应与原来完全一致；仅替换模式附加 "replaced"。
131	            let mut body = json!({
132	                "collection": out.collection,
133	                "accepted": out.accepted,
134	                "inserted": out.inserted,
135	            });
136	            if req.replace {
137	                body["replaced"] = json!(out.replaced);
138	            }
139	            Ok(Json(body))
140	        }
141	        Err(e) => Err(rejection_error(e)),
142	    }
143	}
144	
145	/// `POST /versions`：保存当前各集合数据为只读版本。
146	async fn save_version(State(s): State<Arc<Store>>) -> Result<Response, ApiError> {
147	    let v = s
148	        .save_version()
149	        .map_err(|e| ApiError::new(StatusCode::INTERNAL_SERVER_ERROR, e))?;
150	    Ok((
151	        StatusCode::CREATED,
152	        Json(json!({ "id": v.id, "saved_at": v.saved_at })),
153	    )
154	        .into_response())
155	}
156	
157	/// `GET /versions`：列出已保存的版本。
158	async fn list_versions(State(s): State<Arc<Store>>) -> Json<Value> {
159	    let versions: Vec<Value> = s
160	        .list_versions()
161	        .into_iter()
162	        .map(|v| json!({ "id": v.id, "saved_at": v.saved_at }))
163	        .collect();
164	    Json(json!({ "versions": versions }))
165	}
166	
167	/// `GET /versions/{id}`：版本详情（含集合名列表）。
168	async fn get_version(
169	    State(s): State<Arc<Store>>,
170	    Path(id): Path<u64>,
171	) -> Result<Json<Value>, ApiError> {
172	    let d = s
173	        .get_version(id)
174	        .map_err(|e| lookup_error(e, "version", id))?;
175	    let mut collections = d.collections;
176	    collections.sort();
177	    Ok(Json(json!({
178	        "id": d.id,
179	        "saved_at": d.saved_at,
180	        "collections": collections,
181	    })))
182	}
183	
184	/// `GET /versions/{id}/collections/{collection}/records`：查询版本内集合的全部记录。
185	async fn read_records(
186	    State(s): State<Arc<Store>>,
187	    Path((version_id, collection)): Path<(u64, String)>,
188	) -> Result<Json<Value>, ApiError> {
189	    let records = s
190	        .read_records(version_id, &collection)
191	        .map_err(|e| lookup_error(e, &collection, version_id))?;
192	    Ok(Json(json!({
193	        "version": version_id,
194	        "collection": collection,
195	        "records": records,
196	    })))
197	}
198	
199	/// `GET /versions/{from}/collections/{collection}/diff/{to}`：
200	/// 比较同一集合在两个已保存版本之间的差异（只读，不生成新版本）。
201	async fn diff_versions(
202	    State(s): State<Arc<Store>>,
203	    Path((from, collection, to)): Path<(u64, String, u64)>,
204	) -> Result<Json<Value>, ApiError> {
205	    let d = s
206	        .diff_versions(from, to, &collection)
207	        .map_err(|e| diff_error(e, &collection, from, to))?;
208	    let changed: Vec<Value> = d
209	        .changed
210	        .iter()
211	        .map(|c| {
212	            json!({
213	                "id": c.before["id"],
214	                "before": c.before,
215	                "after": c.after,
216	            })
217	        })
218	        .collect();
219	    Ok(Json(json!({
220	        "from": d.from,
221	        "to": d.to,
222	        "collection": d.collection,
223	        "added": d.added,
224	        "dropped": d.dropped,
225	        "changed": changed,
226	    })))
227	}
228	
229	/// 差异查询的错误映射：版本/集合不存在为 404，起始版本晚于目标版本为 400。
230	fn diff_error(e: DiffError, collection: &str, from: u64, to: u64) -> ApiError {
231	    match e {
232	        DiffError::FromVersionNotFound => {
233	            ApiError::new(StatusCode::NOT_FOUND, format!("version {from} not found"))
234	        }
235	        DiffError::ToVersionNotFound => {
236	            ApiError::new(StatusCode::NOT_FOUND, format!("version {to} not found"))
237	        }
238	        DiffError::CollectionNotFoundInFrom => ApiError::new(
239	            StatusCode::NOT_FOUND,
240	            format!("collection \"{collection}\" not found in version {from}"),
241	        ),
242	        DiffError::CollectionNotFoundInTo => ApiError::new(
243	            StatusCode::NOT_FOUND,
244	            format!("collection \"{collection}\" not found in version {to}"),
245	        ),
246	        DiffError::OutOfOrder => ApiError::new(
247	            StatusCode::BAD_REQUEST,
248	            format!("start version {from} is later than target version {to}"),
249	        ),
250	    }
251	}
252	
253	/// 便于组合状态码与响应体。
254	fn lookup_error(e: LookupError, collection: &str, version: u64) -> ApiError {
255	    match e {
256	        LookupError::VersionNotFound => ApiError::new(
257	            StatusCode::NOT_FOUND,
258	            format!("version {version} not found"),
259	        ),
260	        LookupError::CollectionNotFound => ApiError::new(
261	            StatusCode::NOT_FOUND,
262	            format!("collection \"{collection}\" not found in version {version}"),
263	        ),
264	    }
265	}
266	
267	fn app(store: Arc<Store>) -> Router {
268	    Router::new()
269	        .route("/health", get(health))
270	        .route("/version", get(version))
271	        .route(
272	            "/collections/{collection}/records",
273	            axum::routing::post(write_records),
274	        )
275	        .route(
276	            "/versions",
277	            axum::routing::post(save_version).get(list_versions),
278	        )
279	        .route("/versions/{id}", get(get_version))
280	        .route(
281	            "/versions/{id}/collections/{collection}/records",
282	            get(read_records),
283	        )
284	        .route(
285	            "/versions/{from}/collections/{collection}/diff/{to}",
286	            get(diff_versions),
287	        )
288	        .with_state(store)
289	}
290	
291	#[tokio::main]
292	async fn main() -> Result<(), Box<dyn Error>> {
293	    let bind = env::var("VDE_BIND").unwrap_or_else(|_| "127.0.0.1:8080".to_owned());
294	    let data_dir = env::var("VDE_DATA").unwrap_or_else(|_| "data".to_owned());
295	    let store = Arc::new(Store::open(&data_dir)?);
296	
297	    let listener = tokio::net::TcpListener::bind(&bind).await?;
298	    println!(
299	        "Listening on http://{} (data dir: {})",
300	        listener.local_addr()?,
301	        data_dir
302	    );
303	    axum::serve(listener, app(store))
304	        .with_graceful_shutdown(async {
305	            let _ = tokio::signal::ctrl_c().await;
306	        })
307	        .await?;
308	    Ok(())
309	}
310	
311	#[cfg(test)]
312	mod http_tests;
