122	/// WAL 中的事件：已确认提交的一批写入，或一批删除。
123	///
124	/// 采用 untagged 表示，按字段形状区分：写入事件带 `records`（旧版本 WAL 行也是同一形状，
125	/// 可直接重放），删除事件带字符串数组 `delete`。两种事件在重放时分别按主键 upsert 与
126	/// 按主键删除；`replace` 只影响提交时的冲突校验，不影响重放动作本身。
127	#[derive(Serialize, Deserialize)]
128	#[serde(untagged)]
129	enum WalEvent {
130	    /// 一批写入（upsert）。
131	    Commit {
132	        collection: String,
133	        records: Vec<Record>,
134	        #[serde(default)]
135	        replace: bool,
136	    },
137	    /// 一批删除。
138	    Delete {
139	        collection: String,
140	        delete: Vec<String>,
141	    },
142	}
