185	impl Store {
186	    /// 从数据目录加载或初始化存储，并完成崩溃恢复。
187	    pub fn open(data_dir: impl AsRef<Path>) -> Result<Self, String> {
188	        let data_dir = data_dir.as_ref().to_path_buf();
189	        fs::create_dir_all(&data_dir).map_err(|e| format!("create data dir: {e}"))?;
190	
191	        let mut current: BTreeMap<String, Vec<Record>> = BTreeMap::new();
192	        let mut versions: Vec<VersionSnap> = Vec::new();
193	
194	        // 1. 恢复最近一次快照（若存在）。
195	        let snap_path = data_dir.join("snapshot.json");
196	        if snap_path.exists() {
197	            let bytes = fs::read(&snap_path).map_err(|e| format!("read snapshot: {e}"))?;
198	            let state: PersistedState =
199	                serde_json::from_slice(&bytes).map_err(|e| format!("parse snapshot: {e}"))?;
200	            for c in state.collections {
201	                current.insert(c.name, c.records);
202	            }
203	            for v in state.versions {
204	                versions.push(VersionSnap {
205	                    id: v.id,
206	                    saved_at: v.saved_at,
207	                    data: v
208	                        .collections
209	                        .into_iter()
210	                        .map(|c| (c.name, c.records))
211	                        .collect(),
212	                });
213	            }
214	        }
215	        let next_id = versions.last().map(|v| v.id + 1).unwrap_or(1);
216	
217	        // 2. 重放快照之后的 WAL，并修复崩溃残留的残缺行。
218	        let wal_path = data_dir.join("wal.log");
219	        let mut valid_bytes = 0usize;
220	        if wal_path.exists() {
221	            let content = fs::read_to_string(&wal_path).map_err(|e| format!("read wal: {e}"))?;
222	            let mut rest = content.as_str();
223	            loop {
224	                if rest.is_empty() {
225	                    break;
226	                }
227	                let Some(nl) = rest.find('\n') else {
228	                    // 最后一行没有换行结尾：本服务的提交总是以换行结尾，故必为残缺行。
229	                    break;
230	                };
231	                let line = &rest[..nl];
232	                match serde_json::from_str::<WalEvent>(line) {
233	                    Ok(WalEvent::Commit {
234	                        collection,
235	                        records,
236	                        replace: _,
237	                    }) => {
238	                        apply_commit(&mut current, collection, records);
239	                        valid_bytes += nl + 1;
240	                        rest = &rest[nl + 1..];
241	                    }
242	                    Ok(WalEvent::Delete { collection, delete }) => {
243	                        apply_delete(&mut current, &collection, &delete);
244	                        valid_bytes += nl + 1;
245	                        rest = &rest[nl + 1..];
246	                    }
247	                    Err(_) => break,
248	                }
249	            }
250	            if valid_bytes < content.len() {
251	                let f = fs::OpenOptions::new()
252	                    .write(true)
253	                    .open(&wal_path)
254	                    .map_err(|e| format!("repair wal: {e}"))?;
255	                f.set_len(valid_bytes as u64)
256	                    .map_err(|e| format!("repair wal: {e}"))?;
257	                f.sync_all().ok();
258	            }
259	        }
260	
261	        // 3. 打开 WAL 供后续追加。
262	        let wal = fs::OpenOptions::new()
263	            .create(true)
264	            .append(true)
265	            .open(&wal_path)
266	            .map_err(|e| format!("open wal: {e}"))?;
267	
268	        Ok(Store {
269	            inner: Mutex::new(Inner {
270	                current,
271	                versions,
272	                next_id,
273	                wal,
274	            }),
275	            data_dir,
276	        })
277	    }
278	
279	    /// 批量写入：整批校验通过后原子提交，任一条不合法则整批拒绝、已有数据不变。
280	    ///
281	    /// `replace=false`（默认）时，同主键不同内容整批拒绝；`replace=true` 时允许用
282	    /// 新内容覆盖同主键的已有记录。两种模式下同批主键重复、非法记录等校验完全一致，
283	    /// 且任一记录不合法时整批不生效（包括不会发生任何替换）。
284	    pub fn write_batch(
285	        &self,
286	        collection: &str,
287	        batch: &[Value],
288	        replace: bool,
289	    ) -> Result<WriteOutcome, BatchError> {
290	        if collection.is_empty() {
291	            return Err(BatchError::Rejected(Rejection {
292	                index: 0,
293	                id: None,
294	                reason: "collection name must not be empty".to_string(),
295	            }));
296	        }
297	
298	        let mut st = self.inner.lock().unwrap();
299	
300	        // 阶段 1：逐条校验；任何失败都直接返回，状态未做任何修改。
301	        let mut seen: HashMap<&str, usize> = HashMap::with_capacity(batch.len());
302	        let mut prepared: Vec<Record> = Vec::with_capacity(batch.len());
303	        for (i, raw) in batch.iter().enumerate() {
304	            let rec = match raw {
305	                Value::Object(map) => map,
306	                _ => {
307	                    return Err(BatchError::Rejected(Rejection {
308	                        index: i,
309	                        id: None,
310	                        reason: "record must be a JSON object".to_string(),
311	                    }));
312	                }
313	            };
314	            let id = match rec.get("id") {
315	                None => {
316	                    return Err(BatchError::Rejected(Rejection {
317	                        index: i,
318	                        id: None,
319	                        reason: "missing primary key field \"id\"".to_string(),
320	                    }));
321	                }
322	                Some(Value::String(s)) if !s.is_empty() => s.as_str(),
323	                Some(Value::String(_)) => {
324	                    return Err(BatchError::Rejected(Rejection {
325	                        index: i,
326	                        id: None,
327	                        reason: "primary key \"id\" must be a non-empty string".to_string(),
328	                    }));
329	                }
330	                Some(_) => {
331	                    return Err(BatchError::Rejected(Rejection {
332	                        index: i,
333	                        id: None,
334	                        reason: "primary key \"id\" must be a string".to_string(),
335	                    }));
336	                }
337	            };
338	            if let Some(&first) = seen.get(id) {
339	                return Err(BatchError::Rejected(Rejection {
340	                    index: i,
341	                    id: Some(id.to_string()),
342	                    reason: format!(
343	                        "duplicate id \"{id}\" in the same batch (first at index {first})"
344	                    ),
345	                }));
346	            }
347	            for (field, value) in rec.iter() {
348	                if let Err(msg) = validate_value(value) {
349	                    return Err(BatchError::Rejected(Rejection {
350	                        index: i,
351	                        id: Some(id.to_string()),
352	                        reason: format!("field \"{field}\": {msg}"),
353	                    }));
354	                }
355	            }
356	            seen.insert(id, i);
357	            prepared.push(rec.clone());
358	        }
359	
360	        // 阶段 2：与集合中已有记录冲突检查——replace=false 时同主键不同内容拒绝整批；
361	        // replace=true 时同主键不同内容将在提交阶段覆盖，此处跳过。
362	        if !replace && let Some(existing) = st.current.get(collection) {
363	            for (i, rec) in prepared.iter().enumerate() {
364	                let id = rec["id"].as_str().unwrap();
365	                if let Some(old) = existing.iter().find(|r| r["id"] == id)
366	                    && old != rec
367	                {
368	                    return Err(BatchError::Rejected(Rejection {
369	                        index: i,
370	                        id: Some(id.to_string()),
371	                        reason: format!(
372	                            "collection \"{collection}\" already contains a different record with id \"{id}\""
373	                        ),
374	                    }));
375	                }
376	            }
377	        }
378	
379	        // 阶段 3：先持久化（追加 WAL 并 fsync），成功后才更新内存并确认成功。
380	        let event = WalEvent::Commit {
381	            collection: collection.to_string(),
382	            records: prepared.clone(),
383	            replace,
384	        };
385	        append_wal(&mut st.wal, &event).map_err(BatchError::Persist)?;
386	
387	        let existing = st.current.entry(collection.to_string()).or_default();
388	        let mut inserted = 0usize;
389	        let mut replaced = 0usize;
390	        for rec in prepared {
391	            let id = rec["id"].as_str().unwrap();
392	            match existing.iter().position(|r| r["id"] == id) {
393	                Some(pos) => {
394	                    // 内容相同为幂等写入；内容不同（只可能发生在 replace=true）计为替换。
395	                    if existing[pos] != rec {
396	                        replaced += 1;
397	                    }
398	                    existing[pos] = rec;
399	                }
400	                None => {
401	                    existing.push(rec);
402	                    inserted += 1;
403	                }
404	            }
405	        }
406	
407	        Ok(WriteOutcome {
408	            collection: collection.to_string(),
409	            accepted: batch.len(),
410	            inserted,
411	            replaced,
412	        })
413	    }
414	
415	    /// 批量删除：按给定主键逐条删除当前数据中的记录，整批校验通过后原子提交。
416	    ///
417	    /// 主键在集合中不存在时幂等跳过（计入 `missing`，不报错）；空数组、非字符串或空字符串
418	    /// 元素、同批重复主键都整批拒绝，不删除任何记录。删除不会自动创建集合：对尚不存在的
419	    /// 集合发起的合法删除全部计为 `missing`，内存与快照中都不会留下空集合。
420	    pub fn delete_batch(
421	        &self,
422	        collection: &str,
423	        ids: &[Value],
424	    ) -> Result<DeleteOutcome, BatchError> {
425	        if collection.is_empty() {
426	            return Err(BatchError::Rejected(Rejection {
427	                index: 0,
428	                id: None,
429	                reason: "collection name must not be empty".to_string(),
430	            }));
431	        }
432	
433	        let mut st = self.inner.lock().unwrap();
434	
435	        // 空批次与写入一样整批拒绝。
436	        if ids.is_empty() {
437	            return Err(BatchError::Rejected(Rejection {
438	                index: 0,
439	                id: None,
440	                reason: "delete must be a non-empty array".to_string(),
441	            }));
442	        }
443	
444	        // 阶段 1：逐条校验；任何失败都直接返回，状态未做任何修改（也未触碰 WAL）。
445	        let mut prepared: Vec<String> = Vec::with_capacity(ids.len());
446	        let mut seen: HashMap<&str, usize> = HashMap::with_capacity(ids.len());
447	        for (i, raw) in ids.iter().enumerate() {
448	            let id = match raw {
449	                Value::String(s) if !s.is_empty() => s.as_str(),
450	                Value::String(_) => {
451	                    return Err(BatchError::Rejected(Rejection {
452	                        index: i,
453	                        id: None,
454	                        reason: "delete key \"id\" must be a non-empty string".to_string(),
455	                    }));
456	                }
457	                _ => {
458	                    return Err(BatchError::Rejected(Rejection {
459	                        index: i,
460	                        id: None,
461	                        reason: "delete key must be a string".to_string(),
462	                    }));
463	                }
464	            };
465	            if let Some(&first) = seen.get(id) {
466	                return Err(BatchError::Rejected(Rejection {
467	                    index: i,
468	                    id: Some(id.to_string()),
469	                    reason: format!(
470	                        "duplicate id \"{id}\" in the same batch (first at index {first})"
471	                    ),
472	                }));
473	            }
474	            seen.insert(id, i);
475	            prepared.push(id.to_string());
476	        }
477	
478	        // 阶段 2：先持久化（追加 WAL 并 fsync），成功后才更新内存并确认成功。
479	        let event = WalEvent::Delete {
480	            collection: collection.to_string(),
481	            delete: prepared.clone(),
482	        };
483	        append_wal(&mut st.wal, &event).map_err(BatchError::Persist)?;
484	
485	        // 阶段 3：应用删除；集合不存在或主键缺失均为幂等。
486	        let mut deleted = 0usize;
487	        let mut missing = 0usize;
488	        if let Some(existing) = st.current.get_mut(collection) {
489	            for id in &prepared {
490	                match existing.iter().position(|r| r["id"] == id.as_str()) {
491	                    Some(pos) => {
492	                        existing.remove(pos);
493	                        deleted += 1;
494	                    }
495	                    None => missing += 1,
496	                }
497	            }
498	        } else {
499	            missing = prepared.len();
500	        }
501	
502	        Ok(DeleteOutcome {
503	            collection: collection.to_string(),
504	            accepted: ids.len(),
505	            deleted,
506	            missing,
507	        })
508	    }
