649	/// WAL 重放：按主键 upsert；整批来自同一个 commit 事件。
650	fn apply_commit(
651	    current: &mut BTreeMap<String, Vec<Record>>,
652	    collection: String,
653	    records: Vec<Record>,
654	) {
655	    let entry = current.entry(collection).or_default();
656	    for rec in records {
657	        let id = rec["id"].as_str().expect("validated commit");
658	        match entry.iter().position(|r| r["id"] == id) {
659	            Some(pos) => entry[pos] = rec,
660	            None => entry.push(rec),
661	        }
662	    }
663	}
664	
665	/// WAL 重放：按主键删除；主键缺失保持幂等。集合即使被删空也保留为空列表，
666	/// 这样保存版本后与旧版本做差异比较时，被删记录仍出现在 added 中而非报集合不存在。
667	fn apply_delete(current: &mut BTreeMap<String, Vec<Record>>, collection: &str, ids: &[String]) {
668	    let Some(entry) = current.get_mut(collection) else {
669	        return;
670	    };
671	    for id in ids {
672	        if let Some(pos) = entry.iter().position(|r| r["id"] == id.as_str()) {
673	            entry.remove(pos);
674	        }
675	    }
676	}
