687	/// 完整状态写入 snapshot.json（临时文件 + fsync + 原子重命名 + 目录 fsync）。
688	fn persist_state(dir: &Path, st: &Inner) -> Result<(), String> {
689	    let state = PersistedState {
690	        versions: st
691	            .versions
692	            .iter()
693	            .map(|v| PersistedVersion {
694	                id: v.id,
695	                saved_at: v.saved_at,
696	                collections: v
697	                    .data
698	                    .iter()
699	                    .map(|(name, records)| PersistedCollection {
700	                        name: name.clone(),
701	                        records: records.clone(),
702	                    })
703	                    .collect(),
704	            })
705	            .collect(),
706	        collections: st
707	            .current
708	            .iter()
709	            .map(|(name, records)| PersistedCollection {
710	                name: name.clone(),
711	                records: records.clone(),
712	            })
713	            .collect(),
714	    };
715	    let mut bytes = serde_json::to_vec(&state).map_err(|e| format!("encode snapshot: {e}"))?;
716	    bytes.push(b'\n');
717	
718	    let target = dir.join("snapshot.json");
719	    let tmp = dir.join("snapshot.json.tmp");
720	    {
721	        let mut f = fs::OpenOptions::new()
722	            .create(true)
723	            .write(true)
724	            .truncate(true)
725	            .open(&tmp)
726	            .map_err(|e| format!("write snapshot tmp: {e}"))?;
727	        f.write_all(&bytes)
728	            .and_then(|_| f.flush())
729	            .and_then(|_| f.sync_all())
730	            .map_err(|e| format!("write snapshot tmp: {e}"))?;
731	    }
732	    fs::rename(&tmp, &target).map_err(|e| format!("rename snapshot: {e}"))?;
733	    if let Ok(d) = fs::File::open(dir) {
734	        let _ = d.sync_all();
735	    }
736	    Ok(())
737	}
