739	/// 清空 WAL（其中的提交已固化进 snapshot.json），并重新以追加模式打开。
740	fn truncate_wal(wal: &mut fs::File, wal_path: &Path) -> Result<(), String> {
741	    {
742	        let mut f = fs::OpenOptions::new()
743	            .create(true)
744	            .write(true)
745	            .truncate(true)
746	            .open(wal_path)
747	            .map_err(|e| format!("truncate wal: {e}"))?;
748	        f.flush()
749	            .and_then(|_| f.sync_all())
750	            .map_err(|e| format!("truncate wal: {e}"))?;
751	    }
752	    // 先关闭旧句柄，再以 append 重新打开供后续提交使用。
753	    let reopened = fs::OpenOptions::new()
754	        .append(true)
755	        .open(wal_path)
756	        .map_err(|e| format!("reopen wal: {e}"))?;
757	    *wal = reopened;
758	    Ok(())
759	}
