1097	    // 另有 4 个写入线程持续写入带 w 标记的新记录。
1098	    let mut handles = Vec::new();
1099	    for w in 0..4usize {
1100	        let addr = s.addr.clone();
1101	        let ids: Vec<String> = all_ids
1102	            .iter()
1103	            .enumerate()
