1153	            tokio::time::sleep(std::time::Duration::from_millis(2)).await;
1154	        }
1155	        saved
1156	    });
1157	
1158	    for h in handles {
1159	        h.await.unwrap();
1160	    }
1161	    let saved = saver.await.unwrap();
1162	
1163	    // 任一快照中：预置记录的删除要么整批（5 条一组）可见、要么整组仍在，
1164	    // 不会出现半批删除；写入批次同理（按 w/b 计数只能为 0 或 1）。
1165	    for vid in saved {
1166	        let addr = s.addr.clone();
1167	        let r = tokio::task::spawn_blocking(move || {
1168	            request(
1169	                &addr,
1170	                "GET",
1171	                &format!("/versions/{vid}/collections/items/records"),
1172	                None,
1173	            )
