1185	        // 删除批次的真实形状：writer w 的第 b 批为全局下标 w+4*(5b+k)（k=0..5）。
1186	        for w in 0..4usize {
1187	            for b in 0..10usize {
1188	                let group: Vec<&String> = (0..5).map(|k| &all_ids[w + 4 * (5 * b + k)]).collect();
1189	                let n = group.iter().filter(|id| present.contains(**id)).count();
1190	                assert!(
1191	                    n == 0 || n == group.len(),
