/// 解析查询请求体为条件树；空体按空条件（不筛选）处理。
/// 同一条件对象内字段名重复时整批拒绝（400），并给出可识别的字段路径。
fn parse_conditions(body: &str) -> Result<CondObject, ApiError> {
    let trimmed = body.trim();
    if trimmed.is_empty() {
        return Ok(CondObject::default());
    }
    let dup = Rc::new(RefCell::new(None));
    let seed = CondValueSeed { path: String::new(), dup: dup.clone() };
    let mut de = serde_json::Deserializer::from_str(trimmed);
    let parsed = seed.deserialize(&mut de).and_then(|v| de.end().map(|_| v));
    match parsed {
        Ok(CondValue::Sub(conds)) => Ok(conds),
        Ok(_) => Err(ApiError::new(StatusCode::BAD_REQUEST, "query conditions must be a JSON object")),
        Err(e) => {
            if let Some(path) = dup.borrow_mut().take() {
                Err(ApiError {
                    status: StatusCode::BAD_REQUEST,
                    body: json!({
                        "error": format!("duplicate field \"{path}\" in query conditions"),
                        "field": path,
                    }),
                })
            } else {
                Err(ApiError::new(StatusCode::BAD_REQUEST, e.to_string()))
            }
        }
    }
}
