#[test]
fn query_records_filters_by_conditions() {
    let dir = temp_dir();
    let store = Store::open(&dir).unwrap();
    store.write_batch("users", &[
        json!({"id": "u1", "name": "Ada", "age": 36, "active": true, "meta": {"role": "admin", "tags": {"level": 2}}}),
        json!({"id": "u2", "name": "Lin", "age": 28, "active": false, "meta": null}),
        json!({"id": "u3", "name": "Ada", "age": 36, "meta": {"role": "user"}}),
    ], false).unwrap();
    let v = store.save_version().unwrap();

    let cond = |pairs: Vec<(&str, CondValue)>| CondObject(pairs.into_iter().map(|(k, v)| (k.to_string(), v)).collect());
    let scalar = |v: Value| CondValue::Scalar(v);

    // 单条件标量相等。
    let out = store.query_records(v.id, "users", &cond(vec![("name", scalar(json!("Ada")))])).unwrap();
    assert_eq!(ids_of(&out), vec!["u1", "u3"]);

    // 类型严格：期望整数 36 不命中字符串 "36"；u1 age 是整数。
    ... cond age 36 → u1,u3; cond age "36" → none.

    // 点路径与嵌套子条件等价。
    let flat = store.query_records(v.id, "users", &cond(vec![("meta.role", scalar(json!("admin")))])).unwrap();
    let nested = store.query_records(v.id, "users", &cond(vec![("meta", CondValue::Sub(cond(vec![("role", scalar(json!("admin")))])))])).unwrap();
    assert_eq!(ids_of(&flat), vec!["u1"]);
    assert_eq!(ids_of(&nested), vec!["u1"]);

    // 路径中间层缺失或不是对象：不命中（u2 的 meta 为 null）。
    let out = store.query_records(v.id, "users", &cond(vec![("meta.role.x", scalar(json!(1)))])).unwrap();
    assert!(out.is_empty());

    // 深层嵌套子条件。
    let out = store.query_records(v.id, "users", &cond(vec![("meta", CondValue::Sub(cond(vec![("tags", CondValue::Sub(cond(vec![("level", scalar(json!(2)))])))))])).unwrap();
    assert_eq!(ids_of(&out), vec!["u1"]);

    // 子条件要求对应字段是对象：meta 为 null 不命中空子条件。
    let out = store.query_records(v.id, "users", &cond(vec![("meta", CondValue::Sub(cond(vec![])))])).unwrap();
    assert_eq!(ids_of(&out), vec!["u1", "u3"]);

    // 空条件：返回全部记录，顺序与写入一致。
    let out = store.query_records(v.id, "users", &CondObject::default()).unwrap();
    assert_eq!(ids_of(&out), vec!["u1", "u2", "u3"]);

    // 布尔与 null 匹配。
    let out = store.query_records(v.id, "users", &cond(vec![("active", scalar(json!(true)))])).unwrap();
    assert_eq!(ids_of(&out), vec!["u1"]);
    let out = store.query_records(v.id, "users", &cond(vec![("meta", scalar(json!(null)))])).unwrap();
    assert_eq!(ids_of(&out), vec!["u2"]);

    // 只读：不生成新版本。
    assert_eq!(store.list_versions().len(), 1);

    // 版本/集合不存在。
    assert_eq!(store.query_records(999, "users", &CondObject::default()).unwrap_err(), LookupError::VersionNotFound);
    assert_eq!(store.query_records(v.id, "missing", &CondObject::default()).unwrap_err(), LookupError::CollectionNotFound);

    fs::remove_dir_all(&dir).ok();
}
